40	    min-width: 20px;
41	    min-height: 20px;
42	    border: 1px solid @outline;
43	    border-radius: 10px;
44	}
45	
46	/* Shared geometry for every sprite. The PNGs are alpha-trimmed (originals in
47	   assets/original/), so the sprite's ink fills its canvas and the box size is
48	   the pokemon size. background-size: contain fits the sprite inside the box,
49	   so height lands on 26px only where min-width >= 26 * aspect ratio; wooper is
50	   the widest of the square-ish icons at 1.167:1, needing 30.33px, so 32px
51	   clears all three. */
52	#custom-clock-icon,
53	#network.icon,
54	#bluetooth.icon,
55	#custom-battery-icon {
56	    background-position: center;
