// hyprland/workspaces lives here (not center) so the numbers sit at a fixed
// left position. The centered taskbar changes width per workspace, which would
// re-center anything grouped with it and make the numbers slide on each switch.
"modules-left": ["custom/clock-icon", "custom/divider", "clock", "hyprland/workspaces"],
"modules-center": [
  "custom/taskbar-divider",
  "hyprland/workspaces#taskbar",
],

