/* Shared box for every workspace number button. Identical geometry for active
   and inactive keeps the row from reflowing, and the vertical footprint is
   trimmed (2px padding/margin, not 4px) so the tallest state — the active
   pokeball button — stays well under the bar's 56px height budget. Otherwise it
   sits right at the ceiling and the bar jumps up/down as the pokeball moves. */
#workspaces:not(.taskbar) button {
    padding: 2px 4px;
    margin: 2px 0px;
    min-width: 20px;
    min-height: 20px;
    border: 1px solid transparent;
    border-radius: 10px;
}

